#include <stdio.h>

#define MAXSIZE 100

/* 折半查找 key：找到返回 1 且 *pos 为下标；未找到返回 0 且 *pos 为应插入位置 */
int BinSearchInsert(int a[], int n, int key, int *pos) {
    int low = 0, high = n - 1, mid;

    while (low <= high) {
        mid = (low + high) / 2;
        if (a[mid] == key) {
            *pos = mid;
            return 1;
        } else if (a[mid] > key)
            high = mid - 1;
        else
            low = mid + 1;
    }
    *pos = low;
    return 0;
}

int main(void) {
    int a[MAXSIZE], n, i, key, pos, ok;

    if (scanf("%d", &n) != 1 || n < 0 || n > MAXSIZE)
        return 1;
    for (i = 0; i < n; i++)
        if (scanf("%d", &a[i]) != 1)
            return 1;
    if (scanf("%d", &key) != 1)
        return 1;
    ok = BinSearchInsert(a, n, key, &pos);
    if (ok)
        printf("FOUND %d\n", pos);
    else
        printf("NOTFOUND %d\n", pos);
    return 0;
}

