#include <stdio.h>
#include <stdlib.h>

typedef struct AVLNode {
    int key;
    int height;
    struct AVLNode *left, *right;
} AVLNode;

int H(AVLNode *p) {
    return p == NULL ? 0 : p->height;
}

int Max(int a, int b) {
    return a > b ? a : b;
}

AVLNode *RotateR(AVLNode *y) {
    AVLNode *x = y->left;
    AVLNode *t = x->right;

    x->right = y;
