    int addr = Hash(key);

    while (ht[addr] != NULLKEY)
        addr = (addr + 1) % M;
    ht[addr] = key;
}

/* 查找成功返回所在下标，失败返回 -1 */
int Search(int ht[], int key) {
    int addr = Hash(key);

    while (ht[addr] != NULLKEY) {
        if (ht[addr] == key)
            return addr;
        addr = (addr + 1) % M;
    }
    return -1;
}

