#include <stdio.h>
#include <stdlib.h>

#define M 11

typedef struct Node {
    int key;
    struct Node *next;
} Node;

int Hash(int key) {
    return key % M;
}

/* 头插法把 key 加入同义词链 */
void Insert(Node *ht[], int key) {
    Node *p = (Node *)malloc(sizeof(Node));

    p->key = key;
    p->next = ht[Hash(key)];
    ht[Hash(key)] = p;
}

