problems.stem:
下面的程序用除留余数法 H(key) = key mod 13 与线性探测建立一个散列表，依次插入教材经典例的 12 个关键字 19 14 23 1 68 20 84 27 55 11 10 79，
然后从标准输入读入两个整数 del 与 probe：先删除 del，再查找 probe，打印查找结果与整张表。
程序在删除某个关键字之后，会连原本明明还在表里的关键字也查不到。请找出错误并改正。

```c
#include <stdio.h>
#define M 13
enum { EMPTY = -1, DELETED = -2 };
#define H(key) ((key) % M)
static int table[M];
static int insertKey(int key)
{
    int h = H(key), i;
    for (i = 0; i < M; i++, h = (h + 1) % M) {
        if (table[h] == EMPTY || table[h] == DELETED) { table[h] = key; return h; }
        if (table[h] == key) return h;
    }
    return -1;
}
static int searchKey(int key)
{
    int h = H(key), i;
    for (i = 0; i < M; i++, h = (h + 1) % M)
        if (table[h] == key) return h; else if (table[h] == EMPTY) return -1;
    return -1;
}
static void deleteKey(int key)
{
    int h = searchKey(key);
    if (h >= 0) table[h] = EMPTY;
}
int main(void)
{
    int keys[12] = { 19, 14, 23, 1, 68, 20, 84, 27, 55, 11, 10, 79 };
    int i, del, probe, pos;
    for (i = 0; i < M; i++) table[i] = EMPTY;
    for (i = 0; i < 12; i++) insertKey(keys[i]);
    if (scanf("%d %d", &del, &probe) != 2) return 1;
    deleteKey(del);
    pos = searchKey(probe);
    printf("删除 %d 之后查找 %d：%s（下标 %d）\n", del, probe, pos >= 0 ? "找到" : "找不到", pos);
    for (i = 0, printf("表："); i < M; i++) { if (i > 0) printf(" "); printf("%d", table[i]); }
    printf("\n"); return 0;
}
```

