#include <stdio.h>
#define MAXN 100
int binSearch(int a[], int n, int key, int *cmp){
    int lo = 0, hi = n - 1, mid;
    while (lo <= hi) {
        mid = (lo + hi) / 2;
        (*cmp)++;
        if (a[mid] == key) return mid;
        else if (a[mid] < key) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}
