    for (i = 0; i < n; i++) scanf("%d", &a[i]);
    pos = binSearch(a, n, key, &cmp);
    if (pos < 0) printf("未找到 %d：比较 %d 次\n", key, cmp);
    else printf("找到 %d，下标 %d：比较 %d 次\n", key, pos, cmp);
    return 0;
}
```

