```
5
18 12 47 25 37
25
```

程序：
```c
#include <stdio.h>
#define M 13
int main(void){
    int h[M], n, x, i, p, cmp;
    for (i = 0; i < M; i++) h[i] = -1;
    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%d", &x); p = x % M;
        while (h[p] != -1) p = (p + 1) % M;
        h[p] = x;
    }
    scanf("%d", &x);
    p = x % M; cmp = 0;
    while (h[p] != -1 && h[p] != x) { cmp++; p = (p + 1) % M; }
    if (h[p] == x) printf("找到 %d 位置 %d 比较 %d 次\n", x, p, cmp + 1);
    else printf("未找到 %d 比较 %d 次\n", x, cmp);
    return 0;
}
```

