程序：
```c
#include <stdio.h>
#include <stdlib.h>
#define M 13
typedef struct N { int key; struct N *next; } N;
int main(void){
    N *head[M] = {0}, *p, *q; int n, x, i, pos;
    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%d", &x); pos = x % M;
        p = (N *)malloc(sizeof(N)); p->key = x; p->next = head[pos]; head[pos] = p;
    }
    scanf("%d", &x);
    pos = x % M; q = head[pos];
    while (q != NULL && q->key != x) q = q->next;
    if (q != NULL) printf("找到 %d\n", x);
    else printf("未找到 %d\n", x);
    return 0;
}
```

