problems.stem:
写出下列程序在给定输入下的运行结果（逐行抄写，空格与换行都要一致）。

输入：
```
5 5
3 1 4 9 2
```

程序：
```c
#include <stdio.h>
#define MAX 100
int main(void){
    int n,m,i,k,pos,step,total;
    int table[MAX],used[MAX],probe[MAX],key[MAX];
    scanf("%d %d",&n,&m);
    for(i=0;i<m;i++){table[i]=-1;used[i]=0;}
    for(i=0;i<n;i++){scanf("%d",&key[i]);}
    total=0;
    for(i=0;i<n;i++){
        k=key[i];
        pos=k%m;
        step=0;
        while(used[pos]){
            pos=(pos+1)%m;
            step++;
        }
        used[pos]=1;
        table[pos]=k;
        probe[i]=step+1;
        total+=probe[i];
    }
    for(i=0;i<m;i++){printf("%d",table[i]);if(i<m-1)printf(" ");}
    printf("\n");
    printf("%d\n",total);
    printf("%.2f\n",(double)total/n);
    return 0;
}
```

